163	func saveCachedVersion(path, version string) error {
164		cv := cachedVersion{Version: version, Time: time.Now().UTC()}
165		data, err := json.MarshalIndent(cv, "", "  ")
166		if err != nil {
167			return err
168		}
169		if err := safefs.MkdirAll(filepath.Dir(path), 0o755); err != nil {
170			return err
171		}
172		return safefs.WriteFile(path, data, 0o600)
173	}
