197	// DownloadBinary downloads the latest binary for the current platform.
198	func DownloadBinary(tag string, w io.Writer) (string, error) {
199		osName := runtime.GOOS
200		arch := runtime.GOARCH
201	
202		switch arch {
203		case "amd64", "x86_64":
204			arch = "amd64"
205		case "arm64", "aarch64":
206			arch = "arm64"
207		default:
208			return "", fmt.Errorf("unsupported architecture: %s", arch)
209		}
210	
211		binaryName := fmt.Sprintf("%s-%s-%s", productinfo.BinaryName, osName, arch)
212		// Use default GitHub URL for downloads (not the test override)
213		url := fmt.Sprintf("https://github.com/%s/releases/download/%s/%s", defaultGitHubRepo, tag, binaryName)
214	
215		fmt.Fprintf(w, "Downloading %s from %s...\n", tag, url)
216	
217		// Create temp file
218		tmpFile, err := os.CreateTemp("", productinfo.BinaryName+"-update-*")
219		if err != nil {
220			return "", fmt.Errorf("creating temp file: %w", err)
221		}
222		tmpPath := tmpFile.Name()
223	
224		// Download to temp file
225		client := &http.Client{Timeout: 2 * time.Minute}
226		resp, err := client.Get(url)
227		if err != nil {
228			_ = safefs.Remove(tmpPath)
229			return "", fmt.Errorf("downloading binary: %w", err)
230		}
231		defer resp.Body.Close()
232	
233		if resp.StatusCode != http.StatusOK {
234			body, _ := io.ReadAll(resp.Body)
235			_ = safefs.Remove(tmpPath)
236			return "", fmt.Errorf("download failed (%s): %s", resp.Status, string(body))
237		}
238	
239		// Copy with progress
240		buf := make([]byte, 32*1024)
241		written := int64(0)
242		total := resp.ContentLength
243	
244		for {
245			n, err := resp.Body.Read(buf)
246			if n > 0 {
247				written += int64(n)
248				if total > 0 {
249					progress := float64(written) / float64(total) * 100
250					fmt.Fprintf(w, "\r  Downloading: %.1f%%", progress)
251				}
252			}
253			if err != nil {
254				if err == io.EOF {
255					break
256				}
257				_ = safefs.Remove(tmpPath)
258				return "", fmt.Errorf("download interrupted: %w", err)
259			}
260			if _, writeErr := tmpFile.Write(buf[:n]); writeErr != nil {
261				_ = tmpFile.Close()
262				_ = safefs.Remove(tmpPath)
263				return "", fmt.Errorf("writing temp file: %w", writeErr)
264			}
265		}
266	
267		if err := tmpFile.Close(); err != nil {
268			_ = safefs.Remove(tmpPath)
269			return "", fmt.Errorf("closing temp file: %w", err)
270		}
271	
272		fmt.Fprintln(w) // Newline after progress
273	
274		// Verify download
275		info, err := os.Stat(tmpPath)
276		if err != nil {
277			_ = safefs.Remove(tmpPath)
278			return "", fmt.Errorf("checking downloaded file: %w", err)
279		}
280		if info.Size() < 10*1024 { // At least 10KB for a binary
281			_ = safefs.Remove(tmpPath)
282			return "", fmt.Errorf("downloaded file too small (%d bytes)", info.Size())
283		}
284	
285		// Make executable
286		if err := safefs.Chmod(tmpPath, 0o755); err != nil {
287			_ = safefs.Remove(tmpPath)
288			return "", fmt.Errorf("setting permissions: %w", err)
289		}
290	
291		return tmpPath, nil
292	}
